// Every participant regardless of state. Used to resolve historical message authorship: a member
// who has left or been removed still authored their past messages, so their participant row must
// remain resolvable (active-only ListParticipants would drop them and surface "Unknown").
func (q *Queries) ListAllParticipants(ctx context.Context, conversationID string) ([]ConversationParticipant, error) {
	rows, err := q.db.QueryContext(ctx, listAllParticipants, conversationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ConversationParticipant
	for rows.Next() {
		var i ConversationParticipant
		if err := rows.Scan(
			&i.ID,
			&i.ConversationID,
			&i.AccountID,
			&i.ParticipantType,
			&i.AccountUserID,
			&i.AgentConfigID,
			&i.Role,
			&i.Membership,
			&i.Notifications,
			&i.MutedUntil,
			&i.LastReadMessageID,
			&i.LastReadSequence,
			&i.LastReadAt,
			&i.LastSeenAt,
			&i.HiddenAt,
			&i.AgentTriggerPolicy,
			&i.AgentTriggerKeywords,
			&i.RelationAccountID,
			&i.JoinedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

