func (q *Queries) ListConversationsByResource(ctx context.Context, arg ListConversationsByResourceParams) ([]Conversation, error) {
	rows, err := q.db.QueryContext(ctx, listConversationsByResource,
		arg.AccountID,
		arg.TopicResourceType,
		arg.TopicResourceID,
		arg.LinkResourceType,
		arg.LinkResourceID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Conversation
	for rows.Next() {
		var i Conversation
		if err := rows.Scan(
			&i.ID,
			&i.AccountID,
			&i.Type,
			&i.Audience,
			&i.Title,
			&i.GroupID,
			&i.TopicResourceType,
			&i.TopicResourceID,
			&i.CreatedByParticipantID,
			&i.NextSequence,
			&i.LastMessageID,
			&i.LastMessageAt,
			&i.IsArchived,
			&i.LegalHold,
			&i.WorkflowStatus,
			&i.AssigneeResourceType,
			&i.AssigneeResourceID,
			&i.EmailInboxID,
			&i.EmailExternalAddress,
			&i.Metadata,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listConversationsForUser = `-- name: ListConversationsForUser :many
SELECT
    c.id, c.account_id, c.type, c.audience, c.title, c.group_id, c.topic_resource_type, c.topic_resource_id, c.created_by_participant_id, c.next_sequence, c.last_message_id, c.last_message_at, c.is_archived, c.legal_hold, c.workflow_status, c.assignee_resource_type, c.assignee_resource_id, c.email_inbox_id, c.email_external_address, c.metadata, c.created_at, c.updated_at,
    p.id AS participant_id,
    p.last_read_sequence AS participant_last_read_sequence,
    p.hidden_at AS participant_hidden_at
FROM conversation c
JOIN conversation_participant p
    ON p.conversation_id = c.id AND p.account_user_id = ?
WHERE c.account_id = ?
  AND p.membership = 'active'
  -- Internal conversations only. External customer-facing cases (audience='customer': portal support
  -- and email-bridged threads) live in the support inbox, not a staff member's Messages list.
  AND c.audience = 'internal'
  AND (
    (? IS NULL OR ? = 'active') AND p.hidden_at IS NULL
    OR ? = 'hidden' AND p.hidden_at IS NOT NULL
  )
  AND (? IS NULL OR c.type = ?)
  AND (
    ? IS NULL
    OR c.last_message_at < ?
    OR (c.last_message_at = ? AND c.id < ?)
  )
ORDER BY c.last_message_at DESC, c.id DESC
LIMIT ?
`

type ListConversationsForUserParams struct {
	AccountUserID       sql.NullString
	AccountID           string
	Status              interface{}
	Type                sql.NullString
	CursorLastMessageAt sql.NullTime
	CursorID            sql.NullString
	Limit               int32
}

