const lockConversationSequence = `-- name: LockConversationSequence :one
SELECT next_sequence FROM conversation
WHERE id = ? AND account_id = ?
FOR UPDATE
`

type LockConversationSequenceParams struct {
	ID        string
	AccountID string
}

// Locks the conversation row and returns the next sequence to assign. Must run inside the
// send transaction; the matching UPDATE increments next_sequence under the same lock.
func (q *Queries) LockConversationSequence(ctx context.Context, arg LockConversationSequenceParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, lockConversationSequence, arg.ID, arg.AccountID)
	var next_sequence int64
	err := row.Scan(&next_sequence)
	return next_sequence, err
}

